import { useState, useEffect } from 'react';

export function HitungMundurOTP() {
  const [sisaDetik, setSisaDetik] = useState(60);

  useEffect(() => {
    const timer = setInterval(() => {
      setSisaDetik((d) => (d > 0 ? d - 1 : 0));
    }, 1000);

    return () => clearInterval(timer);  // kompor dimatikan saat layar ditinggalkan
  }, []);

  return <Text>Kirim ulang dalam {sisaDetik} detik</Text>;
}

import { useEffect, useState } from 'react';
import { Keyboard, AppState } from 'react-native';
import type { AppStateStatus } from 'react-native';

export function useKeyboardTerbuka() {
  const [terbuka, setTerbuka] = useState(false);

  useEffect(() => {
    const muncul = Keyboard.addListener('keyboardDidShow', () => setTerbuka(true));
    const hilang = Keyboard.addListener('keyboardDidHide', () => setTerbuka(false));

    return () => {
      muncul.remove();
      hilang.remove();
    };
  }, []);

  return terbuka;
}

// AppState — tahu kapan aplikasi masuk background
useEffect(() => {
  const sub = AppState.addEventListener('change', (status: AppStateStatus) => {
    if (status === 'active') muatUlangSaldo();
  });
  return () => sub.remove();
}, []);

