import { useRef } from 'react';
import { TextInput, View } from 'react-native';

export function FormLogin() {
  const refPassword = useRef<TextInput>(null);

  return (
    <View>
      <TextInput
        placeholder="Email"
        returnKeyType="next"
        onSubmitEditing={() => refPassword.current?.focus()}
      />
      {/* ?. wajib — TS tahu current masih null sebelum komponen terpasang */}
      <TextInput ref={refPassword} placeholder="Password" secureTextEntry />
    </View>
  );
}

import { useRef } from 'react';

export function TombolBayar({ onBayar }: { onBayar: () => Promise<void> }) {
  const sedangProses = useRef(false);  // boolean, bukan state

  const tekan = async () => {
    if (sedangProses.current) return;  // tekan kedua diabaikan
    sedangProses.current = true;
    try {
      await onBayar();
    } finally {
      sedangProses.current = false;
    }
  };

  return <TombolUtama label="Bayar Sekarang" onTekan={tekan} />;
}

